/* ---------- Bar chart ---------- */
.bcx{padding:14px;display:flex;flex-direction:column;gap:12px}
.bcx-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.bcx-h>div:first-child{display:flex;flex-direction:column;font-size:12.5px}
.bcx-v{font-size:14px;font-weight:500;letter-spacing:-.02em}
.bcx-rg button{font-size:12px;height:26px;padding:0 10px}
.bcx-ch{display:flex;align-items:flex-end;gap:8px;height:150px;position:relative}
.bcx-b{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;gap:0;position:relative;cursor:default}
.bcx-st{display:flex;flex-direction:column-reverse;gap:2px;border-radius:7px;overflow:hidden;transition:opacity .25s}
.bcx-st i{display:block;height:0;transition:height .7s var(--ease)}
.bcx-st i:nth-child(1){background:var(--c1)}
.bcx-st i:nth-child(2){background:var(--a3)}
.bcx-st i:nth-child(3){background:var(--bad)}
.bcx-ch:hover .bcx-b:not(:hover) .bcx-st{opacity:.4}
.bcx-l{font-size:11px;color:var(--muted);text-align:center;margin-top:6px;height:14px}
.bcx-tt{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translate(-50%,4px);padding:6px 9px;border-radius:10px;background:var(--ink);color:var(--on-ink);font-size:11.5px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .2s,transform .25s var(--ease);z-index:2;display:flex;flex-direction:column}
.bcx-tt span{opacity:.75}
.bcx-b:hover .bcx-tt{opacity:1;transform:translate(-50%,0)}
.bcx-b:first-child .bcx-tt{left:0;transform:translate(0,4px)}.bcx-b:first-child:hover .bcx-tt{transform:none}
.bcx-b:last-child .bcx-tt{left:auto;right:0;transform:translate(0,4px)}.bcx-b:last-child:hover .bcx-tt{transform:none}
/* on a phone the bars are too thin for the second and second-last tips to sit centred without passing the edge */
@container (max-width:400px){.bcx-b:nth-child(2) .bcx-tt{left:0;transform:translate(0,4px)}.bcx-b:nth-child(2):hover .bcx-tt{transform:none}.bcx-b:nth-last-child(2) .bcx-tt{left:auto;right:0;transform:translate(0,4px)}.bcx-b:nth-last-child(2):hover .bcx-tt{transform:none}}
.bcx-lg{display:flex;gap:14px;font-size:12px;flex-wrap:wrap}
.bcx-lg span{display:flex;align-items:center;gap:6px}
.bcx-lg i{width:8px;height:8px;border-radius:3px}

DM.def('bar-chart', (r, c) => {
  const D = {
    w:{ l:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], d:[[42,9,2],[51,12,3],[48,8,1],[63,10,4],[57,14,2],[18,3,0],[12,2,1]] },
    m:{ l:['W1','W2','W3','W4','W5','W6','W7'], d:[[180,40,9],[210,44,12],[236,51,8],[262,48,10],[251,39,6],[298,52,7],[321,47,5]] }
  };
  const ch = $('.bcx-ch', r), v = $('.bcx-v', r); let tot = 0;
  ch.innerHTML = D.w.l.map(() => `<div class="bcx-b"><div class="bcx-tt"><b class="num"></b><span></span></div><div class="bcx-st"><i></i><i></i><i></i></div><div class="bcx-l"></div></div>`).join('');
  const bars = $$('.bcx-b', ch);
  function draw(k){
    const d = D[k], mx = Math.max(...d.d.map(x => x[0] + x[1] + x[2])) * 1.08, H = ch.clientHeight - 22;
    bars.forEach((b, i) => { const x = d.d[i], s = x[0] + x[1] + x[2];
      c.later(i * 45, () => $$('.bcx-st i', b).forEach((e, j) => e.style.height = Math.max(x[j] ? 3 : 0, x[j] / mx * H) + 'px'));
      $('.bcx-l', b).textContent = d.l[i]; $('.bcx-tt b', b).textContent = s + ' runs'; $('.bcx-tt span', b).textContent = `${x[0]} shipped, ${x[1]} reviewed, ${x[2]} failed`; });
    const t = d.d.reduce((a, x) => a + x[0] + x[1] + x[2], 0); tween(tot, t, 900, n => { tot = n; v.textContent = Math.round(n).toLocaleString('en-US'); });
  }
  seg($('.bcx-rg', r), draw);
  c.later(280, () => draw('w'));
});
